<div class="split-grid"><section class="card"><div class="card-header"><div><h2>Create user</h2><p>New users receive the temporary password Password123!</p></div></div><form method="post" action="<?= e(url('actions.php')) ?>"><input type="hidden" name="csrf" value="<?= e(csrf_token()) ?>"><input type="hidden" name="action" value="create_user"><div class="form-grid"><div class="form-group"><label>Full name</label><input name="full_name" required></div><div class="form-group"><label>Email address</label><input type="email" name="email" required></div><div class="form-group"><label>Role</label><select name="role"><option value="student">Student</option><option value="supervisor">Supervisor</option><option value="admin">Project Coordinator / Admin</option></select></div><div class="form-group"><label>Matric or staff number</label><input name="identifier"></div></div><button class="button" type="submit">Create user</button></form></section><section class="card"><div class="card-header"><h2>Access-control policy</h2></div><div class="callout">Students manage their own project activities. Supervisors access only assigned projects. Administrators control users, assignments and aggregated reports. All passwords are stored using PHP's password hashing API.</div></section></div>
